-- Forever Guide: reads quest, gossip and book text aloud.
-- Two voices: (1) AI clips generated by the companion app, (2) the game's built-in TTS.
local _, FG = ...
local Narrator = {}
FG.Narrator = Narrator

local SOUND_DIR = "Interface\\AddOns\\ForeverGuide_Voices\\sounds\\"

-- Name fragments of common Windows/macOS voices, used when no voice is chosen.
local FEMALE_HINTS = { "zira", "hazel", "susan", "eva", "female", "samantha", "karen", "moira", "tessa", "catherine", "aria", "jenny" }
local MALE_HINTS = { "david", "mark", "george", "james", "male", "daniel", "alex", "fred", "ryan", "guy" }

local current = { handle = nil, key = nil, at = 0 }

local function clips()
    return _G.ForeverGuideVoices or {}
end

function Narrator:Init()
    -- Drop queued texts that the companion app has already voiced.
    local have = clips()
    for key in pairs(FG.db.voiceQueue) do
        if have[key] then FG.db.voiceQueue[key] = nil end
    end

    FG:On("QUEST_DETAIL", function()
        Narrator:Auto("detail", (GetTitleText() or "") .. ". " .. (GetQuestText() or "") .. " " .. (GetObjectiveText() or ""))
    end)
    FG:On("QUEST_PROGRESS", function()
        Narrator:Auto("progress", GetProgressText())
    end)
    FG:On("QUEST_COMPLETE", function()
        Narrator:Auto("complete", GetRewardText())
    end)
    FG:On("QUEST_GREETING", function()
        if FG.settings.readGossip then Narrator:Auto("greeting", GetGreetingText()) end
    end)
    FG:On("GOSSIP_SHOW", function()
        if FG.settings.readGossip and C_GossipInfo and C_GossipInfo.GetText then
            Narrator:Auto("gossip", C_GossipInfo.GetText())
        end
    end)
    FG:On("ITEM_TEXT_READY", function()
        -- Books, letters and plaques.
        Narrator:Auto("book", ItemTextGetText and ItemTextGetText())
    end)
end

function Narrator:Auto(kind, text)
    if FG.settings.autoRead then self:Speak(kind, text) end
end

local function escapePattern(s) return (s:gsub("[%^%$%(%)%%%.%[%]%*%+%-%?]", "%%%0")) end

local function clean(text)
    text = FG.Normalize(text)
    if FG.settings.stripEmotes then
        text = FG.Normalize(text:gsub("<[^>]*>", " "))
    end
    -- Store your name as $N, so voice packs made from quest data work for every character.
    local me = FG.Safe(UnitName("player"))
    if me and me ~= "" then text = text:gsub(escapePattern(me), "$N") end
    return text
end

-- Quest texts are keyed by quest ID, everything else by a hash of the text.
local QUEST_KINDS = { detail = true, progress = true, complete = true, log = true }

function Narrator.Key(kind, text, questID)
    if QUEST_KINDS[kind] and questID and questID > 0 then
        return kind:sub(1, 1) .. questID
    end
    return kind:sub(1, 1) .. FG.Hash(text)
end

local function npcInfo()
    local name = FG.Safe(UnitName("npc"))
    local sex = FG.Safe(UnitSex("npc")) -- 1 unknown, 2 male, 3 female
    return name, sex
end

function Narrator:Speak(kind, rawText, questID)
    local text = clean(rawText)
    if text == "" or text == "." then return end

    questID = questID or (QUEST_KINDS[kind] and kind ~= "log" and FG.Safe(GetQuestID and GetQuestID())) or nil
    local key = Narrator.Key(kind, text, questID)
    -- The quest log says the same as the quest giver, so reuse that clip (e.g. from a zone pack).
    if kind == "log" and questID and not clips()[key] and clips()["d" .. questID] then key = "d" .. questID end
    -- Events can fire twice for the same window; ignore repeats.
    if key == current.key and GetTime() - current.at < 3 then return end
    self:Stop()
    current.key, current.at = key, GetTime()

    local name, sex = npcInfo()
    local mode = FG.settings.mode

    if mode ~= "builtin" and clips()[key] then
        local willPlay, handle = PlaySoundFile(SOUND_DIR .. key .. ".ogg", "Dialog")
        if willPlay then
            current.handle = handle
            return
        end
    end

    if FG.settings.collect and not clips()[key] then
        FG.db.voiceQueue[key] = {
            kind = kind,
            text = text,
            npc = name,
            sex = sex,
            quest = questID,
            locale = GetLocale(),
        }
    end

    if mode ~= "voices" then
        local me = FG.Safe(UnitName("player")) or "adventurer"
        self:SpeakBuiltin(text:gsub("%$N", me), sex, name)
    end
end

-- Picks a built-in voice. With voice variety on, each NPC keeps its own voice and speed,
-- chosen from the voices installed on your computer that match the NPC's sex.
function Narrator:PickVoice(sex, npc)
    local s = FG.settings
    if sex == 3 and s.femaleVoice then return s.femaleVoice, 0 end
    if sex ~= 3 and s.maleVoice then return s.maleVoice, 0 end

    local voices = FG.Try(C_VoiceChat.GetTtsVoices) or {}
    if #voices == 0 then return nil end
    local hints = sex == 3 and FEMALE_HINTS or MALE_HINTS
    local matching = {}
    for _, v in ipairs(voices) do
        local n = (v.name or ""):lower()
        for _, h in ipairs(hints) do
            if n:find(h, 1, true) then table.insert(matching, v.voiceID) break end
        end
    end
    if #matching == 0 then
        for _, v in ipairs(voices) do table.insert(matching, v.voiceID) end
    end
    if not (s.voiceVariety and npc) then return matching[1], 0 end
    local h = tonumber(FG.Hash(npc), 16)
    return matching[h % #matching + 1], (math.floor(h / 7) % 5) - 2
end

function Narrator:SpeakBuiltin(text, sex, npc)
    if not (C_VoiceChat and C_VoiceChat.SpeakText) then
        FG:Print("Built-in text to speech is not available on this client.")
        return
    end
    local voice, rateOffset = self:PickVoice(sex, npc)
    if not voice then
        FG:Print("No TTS voices installed. Add a voice in your operating system's speech settings.")
        return
    end
    local s = FG.settings
    local rate = math.max(-10, math.min(10, s.rate + (rateOffset or 0)))
    if s.ttsLegacy or (FG.Data and FG.Data.tts.speakTextSignature == "legacy") then
        -- Signature before patch 12.0: (voiceID, text, destination, rate, volume)
        C_VoiceChat.SpeakText(voice, text, 1, rate, s.volume)
    else
        -- Signature from patch 12.0, which Forever's client is built on.
        C_VoiceChat.SpeakText(voice, text, rate, s.volume, false)
    end
end

function Narrator:Stop()
    if current.handle then
        StopSound(current.handle)
        current.handle = nil
    end
    if C_VoiceChat and C_VoiceChat.StopSpeakingText then
        pcall(C_VoiceChat.StopSpeakingText)
    end
end

function Narrator:ListVoices()
    local voices = FG.Try(C_VoiceChat.GetTtsVoices) or {}
    if #voices == 0 then
        FG:Print("No built-in voices found.")
        return
    end
    for _, v in ipairs(voices) do
        FG:Print(v.voiceID .. ": " .. tostring(v.name))
    end
end

-- Reads the quest selected in the quest log (or the first quest if none is selected).
function Narrator:ReadQuestLog()
    local questID, title
    if C_QuestLog and C_QuestLog.GetSelectedQuest then
        questID = C_QuestLog.GetSelectedQuest()
        if not questID or questID == 0 then
            for i = 1, C_QuestLog.GetNumQuestLogEntries() do
                local info = C_QuestLog.GetInfo(i)
                if info and not info.isHeader and info.questID then
                    questID = info.questID
                    break
                end
            end
        end
        if not questID or questID == 0 then
            FG:Print("Your quest log is empty.")
            return
        end
        C_QuestLog.SetSelectedQuest(questID)
        title = C_QuestLog.GetTitleForQuestID(questID)
    else
        -- Classic-style quest log API.
        local index = GetQuestLogSelection()
        if not index or index == 0 then index = 1 end
        SelectQuestLogEntry(index)
        title, _, _, _, _, _, _, questID = GetQuestLogTitle(index)
    end

    local description, objectives = GetQuestLogQuestText()
    if not description then
        FG:Print("Could not read the quest text.")
        return
    end
    local text = (title or "") .. ". " .. description .. " " .. (objectives or "")
    -- Quest log text has no NPC, so use the narrator voice (male by default).
    self:Speak("log", text, questID)
end
